<div class="patient-page-heading"><div><span class="eyebrow text-secondary">SEGUIMIENTO DE LA ATENCIÓN</span><h1><?= $escape($title) ?></h1><p class="text-secondary mb-0">Consulta de registros existentes · America/La_Paz</p></div><span class="status-chip is-active">Solo consulta</span></div>
<?php require __DIR__.'/filters.php'; ?>
<section class="patient-card" data-appointment-total="<?= $result['total'] ?>"><div class="schedule-card-heading"><strong><?= $result['total'] ?> citas encontradas</strong><?php if($agenda): ?><span><?= $escape($result['filters']['fecha']) ?></span><?php endif; ?></div>
<?php if(!$result['items']): ?><div class="patient-empty"><h2 class="h5">No hay citas para mostrar</h2><p class="text-secondary">No se encontraron citas dentro de tu ámbito con estos filtros.</p></div><?php else: ?><div class="table-responsive"><table class="table patient-table align-middle mb-0"><caption class="visually-hidden">Citas autorizadas</caption><thead><tr><th>Cita</th><th>Fecha y hora</th><?php if($user['role']!=='Paciente'): ?><th>Paciente</th><?php endif; ?><th>Médico / Especialidad</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>
<?php foreach($result['items'] as $c): ?><tr><td><?= $escape($c['codigo_cita']) ?></td><td><?= $escape($c['fecha']) ?><small class="d-block text-secondary"><?= $escape(\Clinica\Services\ScheduleValidator::displayTime($c['hora_inicio']).'–'.\Clinica\Services\ScheduleValidator::displayTime($c['hora_fin'])) ?></small></td><?php if($user['role']!=='Paciente'): ?><td><?= $escape($c['paciente_nombre']) ?></td><?php endif; ?><td><?= $escape($c['medico_nombre']) ?><small class="d-block text-secondary"><?= $escape($c['especialidad_nombre']) ?></small></td><td><span class="status-chip <?= $c['estado']==='cancelada' ? 'is-inactive' : 'is-active' ?>"><?= $escape(ucfirst($c['estado'])) ?></span></td><td><a href="<?= $escape($base) ?>/detalle?id=<?= $escape($c['id_cita']) ?>" aria-label="Detalle de cita <?= $escape($c['codigo_cita']) ?>">Ver detalle</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<div class="patient-pagination"><span><?= $result['total'] ? 'Mostrando '.(($result['page']-1)*10+1).'–'.min($result['total'],$result['page']*10).' de '.$result['total'] : '0 resultados' ?></span><nav aria-label="Páginas de citas"><ul class="pagination mb-0"><?php $url=static fn(int $page): string=>($agenda ? '/citas/agenda' : $base).'?'.http_build_query(array_filter(array_replace($result['filters'],['pagina'=>$page]),static fn(mixed $v): bool=>$v!==null && $v!=='')); ?>
<?php if($result['page']>1): ?><li class="page-item"><a class="page-link" href="<?= $escape($url($result['page']-1)) ?>">Anterior</a></li><?php endif; ?>
<?php for($i=max(1,$result['page']-2);$i<=min($result['pages'],$result['page']+2);$i++): ?><li class="page-item <?= $i===$result['page'] ? 'active' : '' ?>"><a class="page-link" href="<?= $escape($url($i)) ?>" <?= $i===$result['page'] ? 'aria-current="page"' : '' ?>><?= $i ?></a></li><?php endfor; ?>
<?php if($result['page']<$result['pages']): ?><li class="page-item"><a class="page-link" href="<?= $escape($url($result['page']+1)) ?>">Siguiente</a></li><?php endif; ?></ul></nav></div></section>
